$scanSt=$pdo->prepare("SELECT a.waktu_scan,a.status,a.keterangan,a.metode,s.nis,s.nama FROM absensi_sholat a JOIN siswa s ON s.id=a.siswa_id WHERE a.sesi_id=? ORDER BY a.waktu_scan DESC,a.id DESC LIMIT 100");$scanSt->execute([$id]);$rows=$scanSt->fetchAll();
